#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr getWaterFX ( FSSpec theMeshFSSpec );OSErr getWaterFX ( FSSpec theMeshFSSpec ){//----------------------------------vars-------------------------------------------------- 	short		theMeshFileRef;	OSErr		theError;	char *theMap;	int i, j, k, x, y;	long meshSize, meshWidth, meshHeight;	long PictureSize, PictureWidth, PictureHeight;	Myth256Palette thePalette;	meshHeader theMeshHeader;	gridData *theGrid;//----------------------------------------------------------------------------------------		theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	PictureWidth = meshWidth * 16;	PictureHeight = meshHeight * 16;	PictureSize = PictureWidth * PictureHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	if ( theGrid == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theMap = (char *) NewPtr (PictureSize);	if ( theMap == nil ){		DisposePtr ( (Ptr) theGrid );		FSClose ( theMeshFileRef );		return -1;	}	// make the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}	FileSeek ( theMeshFileRef, 1088L );	FileRead ( theGrid, theMeshHeader.meshLength, theMeshFileRef );	FSClose ( theMeshFileRef );		for ( y = 0, i = 0; y < PictureSize - PictureWidth * 15; y += PictureWidth * 16 ){		for ( x = PictureWidth - 16; x >= 0; x -= 16, i++ ){			for ( k = 0; k < 16; k++ )				for ( j = 0; j < 16; j++ )					theMap[x + y + j + k * PictureWidth] = theGrid[i].water;		}	}	theError = writeBMP( "\p:Graphics.out:waterfx.bmp", PictureWidth, PictureHeight, &thePalette, theMap );	DisposePtr ( (Ptr) theMap );	DisposePtr ( (Ptr) theGrid );	return theError;}